resource.text:
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
.ce-app {
  --bg: #f6f4ee;
  --card: #ffffff;
  --border: #e3e0d5;
  --ink: #18170f;
  --ink-soft: #726f63;
  --ledger: #1f5c4c;
  --brass: #93641e;
  --danger: #a23a2e;
  --font-serif: 'Fraunces', Georgia, serif;
  --font-sans: 'Inter', -apple-system, sans-serif;
  --font-mono: 'IBM Plex Mono', ui-monospace, monospace;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  min-height: 100%;
  width: 100%;
}
.ce-serif {
  font-family: var(--font-serif);
}
.ce-mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.ce-total {
  color: var(--ledger);
}
.ce-total-lg {
  font-size: 1.05rem;
}
.ce-shell {
  max-width: 1100px;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 4rem;
}
.ce-shell-outer {
  display: flex;
  align-items: stretch;
  min-height: 100vh;
}
.ce-sidebar {
  width: 220px;
  flex-shrink: 0;
  background: #fff;
  border-right: 1px solid var(--border);
  padding: 1.4rem 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 1.6rem;
}
.ce-sidebar-brand {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0 0.3rem;
}
.ce-sidebar-brand-text {
  font-size: 1.05rem;
  font-weight: 700;
}
.ce-sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.ce-navitem {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.55rem 0.7rem;
  border-radius: 0.5rem;
  border: none;
  background: transparent;
  color: var(--ink-soft);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  text-align: left;
  width: 100%;
}
.ce-navitem:hover {
  background: #f1efe7;
  color: var(--ink);
}
.ce-navitem-active {
  background: var(--ink);
  color: #fff;
}
.ce-navitem-active:hover {
  background: var(--ink);
  color: #fff;
}
.ce-navitem-disabled {
  color: #c7c4b8;
  cursor: not-allowed;
}
.ce-navitem-soon {
  margin-left: auto;
  font-size: 0.58rem;
  background: #f1efe7;
  color: var(--ink-soft);
  padding: 0.12rem 0.4rem;
  border-radius: 0.3rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
}
.ce-navitem-monitoring {
  border: 1px solid var(--danger);
}
.ce-mainpane {
  flex: 1;
  min-width: 0;
}
@media (max-width: 820px) {
  .ce-shell-outer {
    flex-direction: column;
  }
  .ce-sidebar {
    width: 100%;
    flex-direction: row;
    align-items: center;
    overflow-x: auto;
    padding: 0.7rem 1rem;
    gap: 1rem;
    border-right: none;
    border-bottom: 1px solid var(--border);
  }
  .ce-sidebar-brand {
    flex-shrink: 0;
  }
  .ce-sidebar-nav {
    flex-direction: row;
  }
  .ce-navitem {
    width: auto;
    white-space: nowrap;
  }
  .ce-navitem-soon {
    margin-left: 0.35rem;
  }
}
.ce-header {
  padding-bottom: 1.25rem;
  border-bottom: 1px solid var(--border);
  margin-bottom: 1.5rem;
}
.ce-header-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 0.5rem;
}
.ce-breadcrumb {
  color: var(--ink-soft);
  font-size: 0.85rem;
  letter-spacing: 0.02em;
}
.ce-header-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}
.ce-header-title {
  font-size: 2.25rem;
  font-weight: 600;
  margin: 0.15rem 0;
  line-height: 1.1;
}
.ce-header-title-input {
  font-family: var(--font-serif);
  font-size: 1.6rem;
  font-weight: 600;
  margin: 0.15rem 0;
  width: 100%;
}
.ce-header-subtitle {
  color: var(--ink-soft);
  font-size: 0.95rem;
  margin: 0 0 1rem;
}
.ce-header-total {
  display: flex;
  align-items: baseline;
  gap: 0.6rem;
  background: var(--ink);
  color: #fff;
  border-radius: 0.6rem;
  padding: 0.65rem 1rem;
  width: fit-content;
}
.ce-header-total .ce-field-label {
  color: rgba(255, 255, 255, 0.65);
}
.ce-header-total-val {
  font-size: 1.3rem;
  font-weight: 600;
}
.ce-meta-edit {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  flex: 1;
}
.ce-meta-edit .ce-input {
  max-width: 220px;
}
.ce-import-error {
  background: #fbeae7;
  color: var(--danger);
  border: 1px solid #e7c3bb;
  padding: 0.6rem 0.9rem;
  border-radius: 0.5rem;
  font-size: 0.85rem;
  margin-bottom: 1rem;
}
.ce-tabnav {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 1.5rem;
}
.ce-pill {
  border-radius: 999px;
  border: 1px solid var(--border);
  background: #fff;
  padding: 0.5rem 1.1rem;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--ink);
  cursor: pointer;
  transition: all 0.15s ease;
}
.ce-pill:hover {
  border-color: var(--ink);
}
.ce-pill-active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}
.ce-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 0.85rem;
  overflow: hidden;
}
.ce-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.8rem 1rem;
  background: #faf9f4;
  border-bottom: 1px solid var(--border);
  flex-wrap: wrap;
  gap: 0.5rem;
}
.ce-card-header-compact {
  padding: 0.65rem 0.85rem;
}
.ce-card-header-stats {
  display: flex;
  gap: 1rem;
  font-size: 0.82rem;
  color: var(--ink-soft);
  align-items: baseline;
}
.ce-card-header-stats b {
  color: var(--ink);
}
.ce-chip {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--brass);
  color: var(--brass);
  border-radius: 0.3rem;
  font-size: 0.65rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-weight: 700;
  padding: 0.2rem 0.5rem;
}
.ce-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1rem;
}
.ce-section-title {
  font-size: 1.3rem;
  font-weight: 600;
  margin: 0;
}
.ce-tasks {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.ce-task-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.1rem;
  cursor: pointer;
  gap: 0.75rem;
  flex-wrap: wrap;
}
.ce-task-header-left {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 0;
}
.ce-task-title {
  font-size: 1.15rem;
  font-weight: 600;
  cursor: text;
}
.ce-task-count {
  color: var(--ink-soft);
  font-size: 0.78rem;
}
.ce-task-header-right {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
}
.ce-task-type-select,
.ce-task-duration-input {
  border: 1px solid var(--border);
  border-radius: 0.3rem;
  padding: 0.2rem 0.4rem;
  font-size: 0.78rem;
  background: #fff;
  color: var(--ink);
}
.ce-task-duration-input {
  width: 70px;
}
.ce-task-body {
  padding: 0 1.1rem 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.ce-subtask {
  border: 1px solid var(--border);
  border-radius: 0.7rem;
  overflow: hidden;
}
.ce-subtask-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.7rem 0.9rem;
  background: #faf9f4;
  cursor: pointer;
  gap: 0.6rem;
  flex-wrap: wrap;
}
.ce-subtask-header-left {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
}
.ce-subtask-title {
  font-weight: 600;
  font-size: 0.95rem;
  cursor: text;
}
.ce-subtask-header-right {
  display: flex;
  align-items: center;
  gap: 0.6rem;
}
.ce-subtask-body {
  padding: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  background: #fff;
}

.ce-editable-title {
  cursor: text;
  border-bottom: 1px dashed transparent;
}
.ce-editable-title:hover {
  border-bottom-color: var(--border);
}
.ce-iconbtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.9rem;
  height: 1.9rem;
  border-radius: 0.4rem;
  border: 1px solid transparent;
  background: transparent;
  color: var(--ink-soft);
  cursor: pointer;
}
.ce-iconbtn:hover {
  background: #f1efe7;
  color: var(--ink);
}
.ce-iconbtn-danger:hover {
  background: #fbeae7;
  color: var(--danger);
}
.ce-btn-primary {
  background: var(--ink);
  color: #fff;
  border: 1px solid var(--ink);
  border-radius: 0.5rem;
  padding: 0.5rem 1rem;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}
.ce-btn-primary:hover {
  opacity: 0.88;
}
.ce-btn-ghost {
  background: #fff;
  color: var(--ink);
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  padding: 0.5rem 1rem;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}
.ce-btn-ghost:hover {
  border-color: var(--ink);
}
.ce-btn-sm {
  padding: 0.4rem 0.75rem;
  font-size: 0.76rem;
}
.ce-btn-active {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}
.ce-summary-toggle {
  display: flex;
  gap: 0.4rem;
}
.ce-gridwrap {
  overflow-x: auto;
}
.ce-grid {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.78rem;
  min-width: 760px;
}
.ce-grid th {
  background: #faf9f4;
  color: var(--ink-soft);
  font-size: 0.64rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
  padding: 0.5rem 0.5rem;
  border-bottom: 1px solid var(--border);
  border-right: 1px solid var(--border);
  text-align: left;
  white-space: nowrap;
}
.ce-grid th:last-child,
.ce-grid td:last-child {
  border-right: none;
}
.ce-grid td {
  border-bottom: 1px solid var(--border);
  border-right: 1px solid var(--border);
  padding: 0;
  vertical-align: middle;
}
.ce-grid-row-ghost td {
  background: #fcfbf8;
}
.ce-grid-input,
.ce-grid-select {
  width: 100%;
  border: none;
  background: transparent;
  padding: 0.42rem 0.55rem;
  font-size: 0.78rem;
  font-family: var(--font-sans);
  color: var(--ink);
  box-sizing: border-box;
}
.ce-grid-select {
  cursor: pointer;
}
.ce-grid-input:focus,
.ce-grid-select:focus {
  outline: 2px solid var(--ledger);
  outline-offset: -2px;
  background: #f3f8f6;
}
.ce-grid-input[type='number'] {
  font-family: var(--font-mono);
  text-align: right;
}
.ce-grid-input::placeholder {
  color: #b9b6aa;
  font-style: italic;
}
.ce-grid-subtotal {
  padding: 0.42rem 0.6rem;
  text-align: right;
  font-family: var(--font-mono);
  font-weight: 700;
  color: var(--ledger);
  white-space: nowrap;
}
.ce-grid-del {
  width: 2rem;
  text-align: center;
}
.ce-grid-foot td {
  background: #faf9f4;
  font-weight: 700;
  padding: 0.55rem 0.6rem;
  border-bottom: none;
}
.ce-mini-rows {
  display: flex;
  flex-direction: column;
}
.ce-mini-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem 0.85rem;
  border-bottom: 1px solid var(--border);
  gap: 0.5rem;
}
.ce-mini-row:last-child {
  border-bottom: none;
}
.ce-mini-row-label {
  font-size: 0.78rem;
  color: var(--ink);
  min-width: 0;
}
.ce-mini-row-end {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  flex-shrink: 0;
}
.ce-empty {
  color: var(--ink-soft);
  font-size: 0.8rem;
  text-align: center;
  padding: 1rem;
}
.ce-empty-lg {
  padding: 2.5rem 1rem;
}
.ce-add-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  width: 100%;
  padding: 0.6rem;
  border: none;
  border-top: 1px solid var(--border);
  background: #fff;
  color: var(--ink-soft);
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
}
.ce-add-row:hover {
  background: #faf9f4;
  color: var(--ink);
}
.ce-inline-add {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  padding: 0.5rem;
}
.ce-inline-add-lg {
  padding: 0.9rem;
}
.ce-form {
  padding: 0.9rem;
  border-top: 1px solid var(--border);
  background: #fcfbf8;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}
.ce-assumption {
  font-size: 0.7rem;
  color: var(--ink-soft);
  margin: -0.3rem 0 0;
}
.ce-form-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.6rem;
}
@media (min-width: 640px) {
  .ce-form-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}
.ce-form-scroll {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  white-space: nowrap;
  gap: 0.6rem;
  padding-bottom: 0.25rem;
}
.ce-form-scroll .ce-field {
  min-width: 150px;
  flex: 0 0 auto;
}
.ce-form-scroll .ce-input {
  min-width: 150px;
}
.ce-field {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}
.ce-field-label {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ink-soft);
  font-weight: 600;
}
.ce-input {
  border: 1px solid var(--border);
  border-radius: 0.4rem;
  padding: 0.45rem 0.6rem;
  font-size: 0.82rem;
  font-family: var(--font-sans);
  background: #fff;
  color: var(--ink);
  width: 100%;
  box-sizing: border-box;
}
.ce-input:focus {
  outline: none;
  border-color: var(--ink);
}
.ce-input-disabled {
  background: #f1efe7;
  color: var(--ink-soft);
}
.ce-combobox {
  position: relative;
}
.ce-input-icon {
  position: relative;
  display: flex;
  align-items: center;
}
.ce-input-icon-svg {
  position: absolute;
  left: 0.6rem;
  color: var(--ink-soft);
  pointer-events: none;
}
.ce-input-pad {
  padding-left: 1.9rem;
}
.ce-combobox-panel {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.25rem);
  left: 0;
  right: 0;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
  max-height: 220px;
  overflow-y: auto;
}
.ce-combobox-empty {
  padding: 0.6rem 0.75rem;
  font-size: 0.75rem;
  color: var(--ink-soft);
}
.ce-combobox-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  text-align: left;
  padding: 0.5rem 0.7rem;
  border: none;
  background: transparent;
  font-size: 0.8rem;
  cursor: pointer;
  gap: 0.5rem;
}
.ce-combobox-item:hover {
  background: #faf9f4;
}
.ce-combobox-sub {
  color: var(--ink-soft);
  font-family: var(--font-mono);
  font-size: 0.72rem;
  flex-shrink: 0;
}
.ce-summary-hero {
  padding: 1.25rem 1.5rem;
  margin-bottom: 1rem;
  text-align: center;
}
.ce-summary-grand {
  font-size: 2.4rem;
  font-weight: 600;
  color: var(--ledger);
  margin-top: 0.3rem;
}
.ce-summary-block {
  padding: 1.1rem 1.25rem;
  margin-bottom: 1rem;
}
.ce-summary-heading {
  font-size: 1.05rem;
  font-weight: 600;
  margin: 0 0 0.9rem;
}
.ce-summary-subheading {
  font-size: 0.9rem;
  font-weight: 600;
  margin: 0.5rem 0;
  color: var(--ink-soft);
}
.ce-summary-bars {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}
.ce-summary-bar-row {
  display: grid;
  grid-template-columns: 4.5rem 1fr auto;
  align-items: center;
  gap: 0.7rem;
}
.ce-summary-bar-chip {
  justify-content: center;
}
.ce-summary-bar-track {
  background: #f1efe7;
  border-radius: 999px;
  height: 0.5rem;
  overflow: hidden;
}
.ce-summary-bar-fill {
  background: var(--ledger);
  height: 100%;
  border-radius: 999px;
}
.ce-summary-bar-val {
  font-size: 0.82rem;
  text-align: right;
  min-width: 6.5rem;
}
.ce-table-scroll {
  overflow-x: auto;
}
.ce-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.8rem;
}
.ce-table th {
  text-align: left;
  color: var(--ink-soft);
  font-weight: 600;
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 0.5rem 0.6rem;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}
.ce-table td {
  padding: 0.5rem 0.6rem;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}
.ce-table tfoot td {
  border-bottom: none;
  border-top: 2px solid var(--ink);
  font-weight: 700;
  padding-top: 0.7rem;
}
.ce-right {
  text-align: right;
}
.ce-center {
  text-align: center;
}
.ce-table-cell {
  white-space: normal;
}
.ce-subtotal-row td {
  background: #f8f7f2;
  font-weight: 600;
}
.ce-daytype-header td {
  background: #eff3f2;
  font-weight: 700;
  color: var(--ledger);
}
.ce-shift-header td {
  background: #f5f5f2;
  font-style: italic;
  color: var(--ink-soft);
}
.ce-daytype-total td {
  background: #f1efe7;
  font-weight: 700;
  border-bottom: 2px solid var(--border);
}
.ce-grand-total td {
  background: var(--ink);
  color: #fff;
  font-weight: 700;
}
.ce-grand-total td.ce-right {
  color: #fff;
}

/* Monitoring Dashboard Styles */
.mon-dashboard {
  padding: 1.5rem;
  max-width: 1400px;
  margin: 0 auto;
}
.mon-title {
  font-size: 1.8rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
  color: var(--ink);
}
.mon-summary-cards {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.mon-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1rem 1.5rem;
  min-width: 200px;
}
.mon-card-icon {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
}
.mon-card-label {
  font-size: 0.8rem;
  color: var(--ink-soft);
}
.mon-card-value {
  font-size: 1.8rem;
  font-weight: 700;
  margin-top: 0.25rem;
}
.mon-filter-row {
  margin-bottom: 1.5rem;
}
