/* Slide-out drawer */
.ce-drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  z-index: 900;
}

.ce-drawer {
  position: fixed;
  top: 0;
  right: 0;
  height: 100%;
  width: 80%;
  max-width: 1200px;
  background: #fff;
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.15);
  z-index: 1000;
  display: flex;
  flex-direction: column;
  animation: ce-drawer-slide-in 0.25s ease-out;
}

@keyframes ce-drawer-slide-in {
  from {
    transform: translateX(100%);
  }
  to {
    transform: translateX(0);
  }
}

.ce-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.9rem 1.2rem;
  border-bottom: 1px solid var(--border);
  background: #faf9f6;
}

.ce-drawer-body {
  flex: 1;
  overflow-y: auto;
  padding: 1rem 1.2rem 2rem;
}

.ce-cat-drawer-trigger {
  transition: background 0.15s ease;
}

.ce-cat-drawer-trigger:hover {
  background: #f7f6f2;
}



/* ============ Category Row: chips + expanded content ============ */
.ce-cat-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  width: 100%;
}

.ce-cat-row .ce-cat-item {
  flex: 0 0 auto;
}

/* Compact chip-style category button */
.ce-cat-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.35rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 0.4rem;
  background: #FAF9F4;
  cursor: pointer;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink);
  white-space: nowrap;
  transition: background 0.15s ease;
  user-select: none;
  min-height: 32px;
}

.ce-cat-chip:hover {
  background: #f0eee7;
}

.ce-cat-chip.ce-cat-chip-open {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.ce-cat-chip .ce-cat-total {
  color: var(--ledger);
  font-weight: 600;
}

.ce-cat-chip.ce-cat-chip-open .ce-cat-total {
  color: #d4ead9;
}

.ce-cat-chip .ce-cat-arrow {
  font-size: 0.7rem;
  color: var(--ink-soft);
}

.ce-cat-chip.ce-cat-chip-open .ce-cat-arrow {
  color: #fff;
}

/* Expanded content block */
.ce-cat-expanded {
  flex-basis: 100%;
  width: 100%;
  margin-top: 12px;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  background: #fff;
  padding: 0.75rem;
  overflow-x: auto;
}

.ce-cat-expanded table {
  table-layout: fixed;
  width: 100%;
  border-collapse: collapse;
}

.ce-cat-expanded .ce-grid-input,
.ce-cat-expanded .ce-grid-select {
  width: 100%;
  padding: 6px 4px;
  font-size: 0.85rem;
  box-sizing: border-box;
}

/* Fixed column widths for BOL-style grid tables */
