.ce-cat-expanded .ce-grid th:nth-child(6),
.ce-cat-expanded .ce-grid td:nth-child(6) { width: 90px; }
.ce-cat-expanded .ce-grid th:nth-child(7),
.ce-cat-expanded .ce-grid td:nth-child(7) { width: 60px; }
.ce-cat-expanded .ce-grid th:nth-child(8),
